scripts.script:
args.actor.setupSkill(game.i18n.localize("NAME.Endurance"), {absolute : {difficulty : "hard"}}).then(async test => {
    await test.roll();
    if (test.result.SL < 0)
        args.actor.addCondition("poisoned", Math.abs(test.result.SL))
})

// If the creature currently has a Surprised, Unconscious, or Entangled Condition, it does not gain this Advantage.
const surprised = this.actor.hasCondition("surprised")
const unconscious = this.actor.hasCondition("unconscious")
const entangled = this.actor.hasCondition("entangled")
if (entangled || unconscious || surprised) return

// If, at the beginning of its turn, this creature does not have at least Rating Advantage points, its Advantage pool immediately increases to Rating.
const grimRating = parseInt(this.item.specification.value) || 1
if (grimRating > this.actor.status.advantage.value) {
  this.actor.setAdvantage(grimRating)
}

// If the creature currently has a Surprised, Unconscious, or Entangled Condition, it does not gain this Advantage.
const surprised = this.actor.hasCondition("surprised")
const unconscious = this.actor.hasCondition("unconscious")
const entangled = this.actor.hasCondition("entangled")
if (entangled || unconscious || surprised) return

// If, at the beginning of its turn, this creature does not have at least Rating Advantage points, its Advantage pool immediately increases to Rating.
const grimRating = parseInt(this.item.specification.value) || 1
if (grimRating > this.actor.status.advantage.value) {
  this.actor.setAdvantage(grimRating)
}

let lore = this.effect.name.split("(")[1].split(")")[0].toLowerCase();

if (args.type == "channelling" && args.item.system.lore.value == lore)
    args.prefillModifiers.slBonus  += 1
else if ((args.type == "channelling" || args.type == "cast") && args.item.system.lore.value != lore && args.item.system.lore.value != "petty")
    args.prefillModifiers.slBonus  -= 1

let distracting = await fromUuid("Compendium.wfrp4e-core.items.MVI0lXcg6vvtooAF")
let ward = await fromUuid("Compendium.wfrp4e-core.items.Bvd2aZ0gQUXHfCTh")
let wardData = ward.toObject();
wardData.system.specification.value = "9+"

this.actor.createEmbeddedDocuments("Item", [distracting.toObject(), wardData], {fromEffect : this.effect.id})

this.actor.setupSkill(game.i18n.localize("NAME.Cool"), {absolute : {difficulty : "hard"}}).then(async test => {
      await test.roll();
      if (!test.succeeded)
      {
          await this.actor.addCondition("fatigued")
          if (this.actor.type == "character")
                 this.actor.update({"system.status.corruption.value" : this.actor.system.status.corruption.value + 1})
      }
})

// If the creature currently has a Surprised, Unconscious, or Entangled Condition, it does not gain this Advantage.
const surprised = this.actor.hasCondition("surprised")
const unconscious = this.actor.hasCondition("unconscious")
const entangled = this.actor.hasCondition("entangled")
if (entangled || unconscious || surprised) return

// If, at the beginning of its turn, this creature does not have at least Rating Advantage points, its Advantage pool immediately increases to Rating.
const grimRating = parseInt(this.item.specification.value) || 1
if (grimRating > this.actor.status.advantage.value) {
  this.actor.setAdvantage(grimRating)
}

let lore = this.effect.name.split("(")[1].split(")")[0].toLowerCase();

if (args.type == "channelling" && args.item.system.lore.value == lore)
    args.prefillModifiers.slBonus  += 3
else if ((args.type == "channelling" || args.type == "cast") && args.item.system.lore.value != lore && args.item.system.lore.value != "petty")
    args.prefillModifiers.slBonus  -= 1

await this.actor.addCondition("deafened", 3);

this.actor.setupSkill(game.i18n.localize("NAME.Cool"), {absolute : {difficulty: "difficult"}}).then(async test => {
     await test.roll();
     if (!test.succeeded)
         this.actor.addCondition("broken", 3)
})

// If the creature currently has a Surprised, Unconscious, or Entangled Condition, it does not gain this Advantage.
const surprised = this.actor.hasCondition("surprised")
const unconscious = this.actor.hasCondition("unconscious")
const entangled = this.actor.hasCondition("entangled")
if (entangled || unconscious || surprised) return

// If, at the beginning of its turn, this creature does not have at least Rating Advantage points, its Advantage pool immediately increases to Rating.
const grimRating = parseInt(this.item.specification.value) || 1
if (grimRating > this.actor.status.advantage.value) {
  this.actor.setAdvantage(grimRating)
}
